    s=set()
    for a,b in rules[r]: s|=orbit(a,b)
    return s
# GF(2)[z]/(Phi_m), m prime with 2 primitive -> F(2^(m-1))
def clmul(a,b):
    r=0
    while b:
        if b&1: r^=a
        a<<=1; b>>=1
    return r
class F:
    def __init__(s,m):
        s.m=m; s.d=m-1; s.mod=(1<<m)-1>>0  # placeholder
        s.mod=sum(1<<i for i in range(m))  # Phi_m = 1+z+...+z^{m-1}
    def red(s,a):
        D=s.d
        while a>>D:
            h=a.bit_length()-1
            a^=s.mod<<(h-D)
        return a
    def mul(s,a,b): return s.red(clmul(a,b))
    def pw(s,a,e):
        r=1
        while e:
            if e&1: r=s.mul(r,a)
            a=s.mul(a,a); e>>=1
