from ca import *
m=37
def equiv(r1,r2,m):
    S=support(r1); T=support(r2)
    if len(S)!=len(T): return None
    S=[(a%m,b%m) for a,b in S]; T=[(a%m,b%m) for a,b in T]
    # basis from S
    for i in range(len(S)):
        for j in range(i+1,len(S)):
            (a,b),(c,d)=S[i],S[j]
            det=(a*d-b*c)%m
            if det: break
        if det: break
    inv=pow(det,-1,m)
    Tset=set(T)
    for P in T:
        for Q in T:
            # L with L(a,b)=P, L(c,d)=Q : L = [P Q] * [[a,c],[b,d]]^{-1}
            # [[a,c],[b,d]]^{-1} = inv*[[d,-c],[-b,a]]
            M=[[(P[0]*d-Q[0]*b)*inv%m, (-P[0]*c+Q[0]*a)*inv%m],[(P[1]*d-Q[1]*b)*inv%m,(-P[1]*c+Q[1]*a)*inv%m]]
            if (M[0][0]*M[1][1]-M[0][1]*M[1][0])%m==0: continue
            img={((M[0][0]*u+M[0][1]*v)%m,(M[1][0]*u+M[1][1]*v)%m) for u,v in S}
            if img==Tset: return M
    return None
